/**
 * The mock dataset: a dozen coins at every phase, generated by replaying
 * random trades through the SDK math (see engine.ts). Deterministic per seed,
 * time-anchored to "now" when the module loads.
 */
import { LAMPORTS_PER_SOL, TOTAL_SUPPLY } from "@floored/sdk";
import { PublicKey } from "@solana/web3.js";
import { hashSeed, rng, type Rng } from "./rng";
import {
  SLOT_MS,
  buy,
  newMockCoin,
  redeem,
  sell,
  settleWindow,
  slotAt,
  msAtSlot,
  priceFloor,
  type Ctx,
  type EngineEvent,
  type MockCoin,
} from "./engine";

/** The wallet that "Use demo wallet" connects in mock mode. */
export const DEMO_WALLET: PublicKey = rng(0xdec0de).pubkey();

interface Profile {
  name: string;
  symbol: string;
  description: string;
  ageMin: number;
  steps: number;
  /** Curve coins: stop buying at this share of the graduation SOL. 1 = graduate. */
  target: number;
  sellP: number;
  redeemP: number;
  size: [number, number];
  demo?: number;
  /** Fraction of the timeline at which a whale dumps its whole bag. */
  dumpAt?: number;
  /** Seconds before now at which the whale dumps (brake engaged right now). */
  dumpSecondsAgo?: number;
  socials?: MockCoin["meta"]["socials"];
  /** Real devnet mint for the challenge coin. */
  mint?: string;
}

