const sol = (x: number) => BigInt(Math.max(1, Math.round(x * 1e9)));

function pickHolder(r: Rng, c: MockCoin, exclude?: string): [string, bigint] | null {
  const entries = [...c.holders.entries()].filter(([k, v]) => k !== exclude && v > 0n);
  if (!entries.length) return null;
  return r.pick(entries);
}

function makeCtx(r: Rng, ms: number, events: EngineEvent[]): Ctx {
  return { slot: slotAt(ms), ms, sig: () => r.signature(), record: true, events };
}

/** The crank: serve the queue at every window boundary up to `ms`. */
export function crankUntil(c: MockCoin, r: Rng, ms: number, events: EngineEvent[]): void {
  let guard = 0;
  while (c.state.brake.queuedTotal > 0n && guard++ < 500) {
    const nextMs = msAtSlot(c.state.brake.windowStart + c.state.params.brakeWindowSlots) + SLOT_MS / 2;
    if (nextMs > ms) break;
    settleWindow(c, makeCtx(r, nextMs, events));
  }
}

function safe<T>(f: () => T): T | null {
  try {
    return f();
  } catch {
    return null;
  }
}

function build(p: Profile, _idx: number, now: number): MockCoin {
  const r = rng(hashSeed(p.symbol) ^ 0x51ab);
  const users = Array.from({ length: 34 }, () => r.pubkey().toBase58());
  const whale = r.pubkey().toBase58();
  const createdMs = now - p.ageMin * 60_000;
  const mint = p.mint ? new PublicKey(p.mint) : r.pubkey();
  const creator = r.pubkey();
  const c = newMockCoin(
    { name: p.name, symbol: p.symbol, description: p.description, image: "", socials: p.socials ?? {}, createdMs, graduatedMs: null },
    mint,
    creator,
  );
  const events: EngineEvent[] = [];
  const end = now - (p.dumpSecondsAgo ? (p.dumpSecondsAgo + 4) * 1000 : r.range(5, 50) * 1000);
  const span = Math.max(1, end - createdMs);
  const times = clusteredTimes(r, p.steps, createdMs, span);
  const dumpIndex = p.dumpAt !== undefined ? Math.floor(p.steps * p.dumpAt) : -1;
  const gradSol = c.state.params.graduationSol;

  // The creator and (for dump profiles) the whale buy first.
  safe(() => buy(c, creator.toBase58(), sol(r.range(0.5, 2)), makeCtx(r, createdMs + 2000, events)));
  if (p.dumpAt !== undefined || p.dumpSecondsAgo !== undefined) {
    safe(() => buy(c, whale, sol(24), makeCtx(r, createdMs + 9000, events)));
  }

  let dumped = false;
  times.forEach((ms, i) => {
    crankUntil(c, r, ms, events);
    const ctx = makeCtx(r, ms, events);
    // The dev dumps once the coin has graduated (the challenge is about the floor).
    if (dumpIndex >= 0 && !dumped && i >= dumpIndex && c.state.phase === 1) {
      dumped = true;
      const bag = c.holders.get(whale) ?? 0n;
      if (bag > 0n) safe(() => sell(c, whale, bag, true, ctx));
      return;
    }
    if (p.demo && (i === Math.floor(p.steps * 0.22) || i === Math.floor(p.steps * 0.71))) {
      safe(() => buy(c, DEMO_WALLET.toBase58(), sol(p.demo! * (i < p.steps / 2 ? 1 : 0.5)), ctx));
      return;
    }
    const curve = c.state.phase === 0;
    const progress = curve ? Number((c.state.realSol * 1000n) / gradSol) / 1000 : 1;
    const wantBuy = curve ? progress < p.target : true;
    const roll = r.next();
    if (!curve && roll < p.redeemP) {
      const h = pickHolder(r, c, whale);
      if (h) safe(() => redeem(c, h[0], (h[1] * BigInt(r.int(30, 100))) / 100n, ctx));
      return;
    }
    // While a coin is still climbing its curve, sellers take profits in smaller bites.
    const climbing = curve && progress < p.target;
    const sellP = climbing ? p.sellP * 0.45 : p.sellP;
    if (roll < p.redeemP + sellP || !wantBuy) {
      const h = pickHolder(r, c, whale);
      if (h && h[0] !== DEMO_WALLET.toBase58()) {
        const amt = (h[1] * BigInt(climbing ? r.int(10, 45) : r.int(15, 100))) / 100n;
        if (amt > 0n) safe(() => sell(c, h[0], amt, true, ctx));
      }
      return;
    }
    let size = r.skew(p.size[0], p.size[1]);
    if (curve && p.target < 1) {
      // Do not overshoot the target progress.
      const room = Number(gradSol) * (p.target - progress) / 1e9;
      size = Math.min(size, Math.max(0.02, room * 1.02));
    }
    safe(() => buy(c, r.pick(users), sol(size), ctx));
  });

  if (p.dumpSecondsAgo !== undefined) {
    const ms = now - p.dumpSecondsAgo * 1000;
    crankUntil(c, r, ms - 1, events);
    // A big dump right now: the brake catches it and queues the rest.
    const bag = c.holders.get(whale) ?? 0n;
    if (bag > 0n) safe(() => sell(c, whale, bag, true, makeCtx(r, ms, events)));
    // The demo wallet panics too: part of its bag goes to the queue.
    const demoBag = c.holders.get(DEMO_WALLET.toBase58()) ?? 0n;
    if (demoBag > 0n) safe(() => sell(c, DEMO_WALLET.toBase58(), demoBag / 3n, true, makeCtx(r, ms + 2400, events)));
  } else {
    crankUntil(c, r, now, events);
  }
  return c;
}

/**
 * Trade times that look like a real memecoin: a rush at launch that decays,
 * then bursts of activity separated by quiet stretches. Exponential gaps whose
 * mean drifts as a slow random walk (volatility clustering), rescaled to fit
 * the coin's life. Sorted, deterministic from the rng.
 */
function clusteredTimes(r: Rng, n: number, start: number, span: number): number[] {
  if (n <= 0) return [];
  const gaps: number[] = [];
  let mood = 0;
  for (let i = 0; i < n; i++) {
    mood = Math.max(-2.2, Math.min(2.2, mood * 0.92 + (r.next() - 0.5) * 0.9));
    const launch = 1 + 6 * Math.exp(-i / Math.max(4, n * 0.06));
    const burst = r.chance(0.07) ? 0.08 : 1;
    const mean = (Math.exp(mood) * burst) / launch;
    gaps.push(-Math.log(1 - r.next() * 0.999) * mean);
  }
  const total = gaps.reduce((a, b) => a + b, 0) || 1;
  let t = start;
  return gaps.map((g) => (t += (g / total) * span));
}

export interface Dataset {
  coins: MockCoin[];
  byMint: Map<string, MockCoin>;
  bootMs: number;
  lastAdvanceMs: number;
  /** Platform totals that predate the coins in this dataset (so the counters look like a live platform). */
  baseline: { redeemedLamports: bigint; coinsCreated: number; coinsGraduated: number; brakes: number; rugsAvoided: number; byDay: { day: string; lamports: bigint; count: number }[] };
  activity: Rng;
}

function baselineSeries(now: number) {
  const r = rng(0xf100d);
  const days: { day: string; lamports: bigint; count: number }[] = [];
  let total = 0n;
  for (let d = 44; d >= 1; d--) {
    const date = new Date(now - d * 86_400_000);
    const growth = 1 + (44 - d) / 14;
    const lamports = sol(r.range(18, 46) * growth + (r.chance(0.12) ? r.range(40, 90) : 0));
    total += lamports;
    days.push({ day: date.toISOString().slice(0, 10), lamports, count: Math.round(r.range(40, 120) * growth) });
  }
  return { days, total };
}

export function createDataset(now = Date.now()): Dataset {
  const coins = PROFILES.map((p, i) => build(p, i, now));
  const { days, total } = baselineSeries(now);
  return {
    coins,
    byMint: new Map(coins.map((c) => [c.state.mint.toBase58(), c])),
    bootMs: now,
    lastAdvanceMs: now,
    baseline: { redeemedLamports: total, coinsCreated: 1271, coinsGraduated: 214, brakes: 96, rugsAvoided: 31, byDay: days },
    activity: rng((now & 0xffffffff) >>> 0),
  };
}

/**
 * Live activity: random trades across the dataset and the crank serving the
 * queues. Both the mock API (server) and the mock websocket (browser) call it.
 */
export function randomAction(ds: Dataset, ms: number): EngineEvent[] {
  const r = ds.activity;
  const events: EngineEvent[] = [];
  // Arbitrage: below the floor, buying and redeeming is free money, so somebody buys.
  const cheap = ds.coins.find((c) => {
    if (c.state.phase !== 1) return false;
    const { price, floor } = priceFloor(c);
    return floor > 0 && price < floor * 0.99;
  });
  if (cheap && r.chance(0.55)) {
    const ctx: Ctx = { slot: slotAt(ms), ms, sig: () => r.signature(), record: true, events };
    safe(() => buy(cheap, r.pubkey().toBase58(), sol(r.range(1.5, 4.5)), ctx));
    return events;
  }
  // Busy coins trade more; brand-new ones occasionally.
  const weights = ds.coins.map((c) => (c.state.phase === 1 ? 3 : 2) + (c.state.brake.queuedTotal > 0n ? 2 : 0));
  const total = weights.reduce((a, b) => a + b, 0);
  let x = r.next() * total;
  let c = ds.coins[0]!;
  for (let i = 0; i < ds.coins.length; i++) {
    x -= weights[i]!;
    if (x <= 0) {
      c = ds.coins[i]!;
      break;
    }
  }
  const ctx: Ctx = { slot: slotAt(ms), ms, sig: () => r.signature(), record: true, events };
  const roll = r.next();
  const graduated = c.state.phase === 1;
  const user = r.pubkey().toBase58();
  if (graduated && roll < 0.16) {
    const h = pickHolder(r, c, DEMO_WALLET.toBase58());
    if (h) safe(() => redeem(c, h[0], (h[1] * BigInt(r.int(20, 100))) / 100n, ctx));
  } else if (roll < 0.5) {
    const h = pickHolder(r, c, DEMO_WALLET.toBase58());
    if (h) safe(() => sell(c, h[0], (h[1] * BigInt(r.int(10, 70))) / 100n, true, ctx));
  } else {
    // Keep curve coins from graduating too quickly in a demo session.
    const near = !graduated && Number((c.state.realSol * 100n) / c.state.params.graduationSol) > 97;
    if (!near) safe(() => buy(c, user, sol(r.skew(0.03, graduated ? 2.4 : 1.2)), ctx));
  }
  return events;
}

/** Serve elapsed brake windows on every coin up to `ms`. */
export function crankAll(ds: Dataset, ms: number): EngineEvent[] {
  const events: EngineEvent[] = [];
  for (const c of ds.coins) crankUntil(c, ds.activity, ms, events);
  return events;
}

/** Keep the demo honest: if the brake coin's queue ran dry long ago, somebody dumps again. */
export function keepBrakeDemoAlive(ds: Dataset, ms: number): EngineEvent[] {
  const c = ds.coins.find((x) => x.meta.symbol === "GRVL");
  if (!c || c.state.brake.queuedTotal > 0n || c.state.phase !== 1) return [];
  const lastRelease = [...c.queueEvents].reverse().find((e) => e.kind === "released");
  if (lastRelease && ms - lastRelease.ms < 150_000) return [];
  const h = [...c.holders.entries()].filter(([k]) => k !== DEMO_WALLET.toBase58()).sort((a, b) => (b[1] > a[1] ? 1 : -1))[0];
  if (!h) return [];
  const events: EngineEvent[] = [];
  const r = ds.activity;
  safe(() => sell(c, h[0], h[1], true, { slot: slotAt(ms), ms, sig: () => r.signature(), record: true, events }));
  return events;
}

/** Catch the dataset up with wall-clock time (server side, on each request). */
export function advanceTo(ds: Dataset, ms: number): void {
  if (ms <= ds.lastAdvanceMs) return;
  const elapsed = ms - ds.lastAdvanceMs;
  const n = Math.min(40, Math.floor(elapsed / 3500));
  for (let i = 1; i <= n; i++) {
    const t = ds.lastAdvanceMs + (elapsed * i) / (n + 1);
    crankAll(ds, t);
    randomAction(ds, t);
  }
  crankAll(ds, ms);
  keepBrakeDemoAlive(ds, ms);
  ds.lastAdvanceMs = ms;
}

export const SUPPLY = TOTAL_SUPPLY;
export const LPS = LAMPORTS_PER_SOL;
